<?php
declare(strict_types=1);

final class Posts
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function fail(string $message='Dữ liệu bài viết không hợp lệ.'):never{throw new HttpError(400,$message);}
    private static function text(array $input,string $key,int $max,bool $required=false,bool $trim=true):string
    {
        $v=$input[$key] ?? ($required?null:'');if(!is_string($v))self::fail('Trường '.$key.' không hợp lệ.');if($trim)$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null||($required&&$v==='')||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>$max)self::fail('Trường '.$key.' không hợp lệ.');return $v;
    }
    private static function slug(mixed $v):bool{return is_string($v)&&strlen($v)<=160&&(bool)preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D',$v);}
    public static function validate(array $input):array
