        foreach(['relatedProductIds'=>[12,80],'relatedRideIds'=>[24,180]] as $key=>[$max,$length]){$values=$input[$key] ?? [];if(!is_array($values)||!array_is_list($values)||count($values)>$max)self::fail();foreach($values as $v)if(!is_string($v)||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>$length||($key==='relatedRideIds'&&$v===''))self::fail();$p[$key]=$values;}
        if(array_key_exists('english',$input)){$en=$input['english'];if(!is_array($en)||array_diff(array_keys($en),['slug','title','excerpt','contentHtml','seoTitle','seoDescription','category','status','sourceHash']))self::fail('Bản English không hợp lệ.');$en['status']=$en['status'] ?? 'DRAFT';if(!in_array($en['status'],['DRAFT','PUBLISHED','NEEDS_REVIEW'],true))self::fail();$e=[];foreach(['title'=>200,'excerpt'=>1000,'contentHtml'=>200000,'seoTitle'=>200,'seoDescription'=>500,'category'=>100] as $key=>$max)$e[$key]=self::text($en,$key,$max,false,$key==='category');$e['contentHtml']=ContentHtml::clean($e['contentHtml']);$e['status']=$en['status']==='NEEDS_REVIEW'?'PUBLISHED':$en['status'];if(isset($en['slug'])&&$en['slug']!==''&&!self::slug($en['slug']))self::fail();$e['slug']=$en['slug'] ?? '';if(isset($en['sourceHash'])){if(!is_string($en['sourceHash'])||!preg_match('/^[a-f0-9]{64}$/D',$en['sourceHash']))self::fail();$e['sourceHash']=$en['sourceHash'];}$p['english']=$e;}
        if($p['status']==='PUBLISHED'&&trim(strip_tags($p['contentHtml']))==='')self::fail('Bài xuất bản cần nội dung chữ.');return $p;
    }
    private function unpack(array $row):array{$p=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$p+=['excerpt'=>'','contentHtml'=>'','cover'=>null,'category'=>'Cẩm nang','publishedAt'=>null,'seoTitle'=>'','seoDescription'=>'','relatedProductIds'=>[],'relatedRideIds'=>[],'featured'=>false];if(isset($p['english']))$p['english']+=['slug'=>'','title'=>'','excerpt'=>'','contentHtml'=>'','category'=>'','seoTitle'=>'','seoDescription'=>'','status'=>'DRAFT'];$p['version']=(int)$row['version'];$p['updatedAt']=str_replace(' ','T',$row['updated_at']).'Z';return $p;}
    private static function translated(array $p):bool{return in_array($p['english']['status'] ?? '',['PUBLISHED','NEEDS_REVIEW'],true);}
    private static function visible(array $p,string $lang):bool{return $p['status']==='PUBLISHED'&&(!$p['publishedAt']||(float)(new DateTimeImmutable($p['publishedAt']))->format('U.u')<=microtime(true))&&($lang!=='en'||self::translated($p));}
    private function view(array $p,string $lang):array
    {
        if(!self::visible($p,$lang))throw new HttpError(404,'Bài viết chưa xuất bản.');$out=$p;unset($out['version'],$out['english']);$paths=['vi'=>'/cam-nang/'.$p['slug']];if(self::translated($p))$paths['en']='/en/blog/'.($p['english']['slug'] ?: $p['slug']);$out['localePaths']=$paths;$out['languages']=array_keys($paths);
        if($lang==='en'){foreach(['title','excerpt','contentHtml','seoTitle','seoDescription'] as $key)$out[$key]=$p['english'][$key];$out['slug']=$p['english']['slug'] ?: $p['slug'];$dictionary=$this->query('SELECT english_name FROM jingo_post_categories WHERE name=?',[$p['category']])->fetchColumn();$out['category']=$dictionary!==false&&$dictionary!==null?($dictionary ?: $p['category']):($p['english']['category'] ?: ($p['category']==='Cẩm nang'?'Travel guide':$p['category']));}$out['contentHtml']=ContentHtml::clean($out['contentHtml']);return $out;
    }
    public function list(bool $admin=false,string $lang='vi'):array
    {
        $items=[];foreach($this->query('SELECT data,version,updated_at FROM jingo_posts ORDER BY updated_at DESC,id')->fetchAll(PDO::FETCH_ASSOC) as $row){$p=$this->unpack($row);if($admin)$items[]=$p;elseif(self::visible($p,$lang)){$p=$this->view($p,$lang);unset($p['contentHtml']);$items[]=$p;}}if(!$admin)usort($items,fn($a,$b)=>((float)(new DateTimeImmutable($b['publishedAt'] ?: $b['updatedAt']))->format('U.u')<=>(float)(new DateTimeImmutable($a['publishedAt'] ?: $a['updatedAt']))->format('U.u')));return $items;
    }
    public function find(string $slug,string $lang='vi'):array
    {
        $items=$this->list(true);foreach($items as $p)if(($lang==='en'?($p['english']['slug'] ?? '') ?: $p['slug']:$p['slug'])===$slug)return $this->view($p,$lang);$id=$this->query('SELECT entity_id FROM jingo_slug_aliases WHERE kind=? AND slug=?',[$lang==='en'?'POST_EN':'POST',$slug])->fetchColumn();foreach($items as $p)if($p['id']===$id)return $this->view($p,$lang);throw new HttpError(404,'Không tìm thấy bài viết.');
    }
    public function categories():array{return $this->query('SELECT name,english_name,version FROM jingo_post_categories ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);}
    public function revisions(string $id):array{if(!$this->query('SELECT id FROM jingo_posts WHERE id=?',[$id])->fetchColumn())throw new HttpError(404,'Không tìm thấy bài viết.');$rows=$this->query('SELECT version,data,saved_by,reason,created_at FROM jingo_post_revisions WHERE post_id=? ORDER BY version DESC LIMIT 50',[$id])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['version']=(int)$r['version'];$r['data']=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);}unset($r);return $rows;}
    private function reserve(string $kind,string $id,string $slug,?string $old):void
    {
        $owner=$this->query('SELECT entity_id FROM jingo_slug_aliases WHERE kind=? AND slug=?',[$kind,$slug])->fetchColumn();if($owner!==false&&$owner!==$id)throw new HttpError(409,'Đường dẫn đã được dùng.');$this->query('DELETE FROM jingo_slug_aliases WHERE kind=? AND slug=? AND entity_id=?',[$kind,$slug,$id]);if($old&&$old!==$slug)$this->query('INSERT INTO jingo_slug_aliases(kind,slug,entity_id) VALUES (?,?,?)',[$kind,$old,$id]);
    }
    public function restore(string $id,array $input,string $actor):array
    {
        if(array_diff(array_keys($input),['version','revision']))self::fail();foreach(['version','revision'] as $key)if(!is_int($input[$key] ?? null)||$input[$key]<1||$input[$key]>2147483646)self::fail('Phiên bản không hợp lệ.');$current=$this->query('SELECT id,slug,version FROM jingo_posts WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);if(!$current)throw new HttpError(404,'Không tìm thấy bài viết.');if((int)$current['version']!==$input['version'])throw new HttpError(409,'Bài viết đã thay đổi. Tải lại trước khi khôi phục.');$saved=$this->query('SELECT data FROM jingo_post_revisions WHERE post_id=? AND version=?',[$id,$input['revision']])->fetchColumn();if($saved===false)throw new HttpError(404,'Không tìm thấy phiên bản.');$payload=json_decode($saved,true,512,JSON_THROW_ON_ERROR);unset($payload['updatedAt'],$payload['views']);$payload['id']=$current['id'];$payload['slug']=$current['slug'];$payload['version']=$input['version'];$payload['status']='DRAFT';$payload['publishedAt']=null;if(isset($payload['english']))$payload['english']['status']='DRAFT';return $this->save($payload,$actor,'RESTORE');
    }
    public function save(array $input,string $actor,string $reason='SAVE'):array
    {
        if(!in_array($reason,['SAVE','RESTORE'],true))throw new LogicException('Unsupported internal save reason.');
        $p=self::validate($input);$this->db->beginTransaction();try{
            if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$row=$this->query('SELECT data,version,updated_at FROM jingo_posts WHERE id=? FOR UPDATE',[$p['id']])->fetch(PDO::FETCH_ASSOC);if(($row&&(int)$row['version']!==$p['version'])||(!$row&&$p['version']!==0))throw new HttpError(409,'Bài viết đã thay đổi. Tải lại trước khi lưu.');$old=$row?$this->unpack($row):null;if($old&&$reason==='SAVE'){unset($p['english']);if(isset($old['english']))$p['english']=$old['english'];}
            if($p['status']==='PUBLISHED'&&$p['publishedAt']===null)$p['publishedAt']=$old&&$old['status']==='PUBLISHED'?($old['publishedAt'] ?: $old['updatedAt']):gmdate('Y-m-d\TH:i:s\Z');
            $ids=ContentHtml::imageIds($p['contentHtml']);if(isset($p['english']))$ids=array_merge($ids,ContentHtml::imageIds($p['english']['contentHtml']));if($p['cover'])$ids[]=$p['cover']['id'];(new Media($this->db,''))->validateIds($ids);foreach(array_unique($p['relatedProductIds']) as $id)if(!$this->query('SELECT id FROM jingo_products WHERE id=?',[$id])->fetchColumn())self::fail('Sản phẩm liên quan không tồn tại.');
            foreach($this->list(true) as $other)if($other['id']!==$p['id']&&($other['slug']===$p['slug']||isset($p['english'])&&(($other['english']['slug'] ?? '') ?: $other['slug'])===($p['english']['slug'] ?: $p['slug'])))throw new HttpError(409,'Đường dẫn bài viết đã tồn tại.');$this->reserve('POST',$p['id'],$p['slug'],$old['slug'] ?? null);if(isset($p['english'])){$p['english']['slug']=$p['english']['slug'] ?: $p['slug'];$this->reserve('POST_EN',$p['id'],$p['english']['slug'],$old?($old['english']['slug'] ?? $old['slug']):null);}
            if($row)$this->query("INSERT INTO jingo_post_revisions(post_id,version,data,saved_by,reason,created_at) SELECT id,version,data,'legacy','BASELINE',updated_at FROM jingo_posts WHERE id=? AND NOT EXISTS(SELECT 1 FROM jingo_post_revisions WHERE post_id=? AND version=?)",[$p['id'],$p['id'],$p['version']]);$p['version']++;$json=json_encode($p,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
            if($row)$this->query('UPDATE jingo_posts SET slug=?,data=?,version=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[$p['slug'],$json,$p['version'],$p['id']]);else $this->query('INSERT INTO jingo_posts(id,slug,data,version) VALUES (?,?,?,?)',[$p['id'],$p['slug'],$json,$p['version']]);
            $this->query("INSERT INTO jingo_post_revisions(post_id,version,data,saved_by,reason,created_at) SELECT id,version,data,?,?,updated_at FROM jingo_posts WHERE id=?",[$actor,$reason,$p['id']]);if($p['category']!=='')$this->query('INSERT INTO jingo_post_categories(name) VALUES (?) ON DUPLICATE KEY UPDATE name=name',[$p['category']]);$this->query('INSERT INTO jingo_post_metrics(post_id) VALUES (?) ON DUPLICATE KEY UPDATE post_id=post_id',[$p['id']]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,$reason==='RESTORE'?'post.restore':'post.save',$p['id']]);$saved=$this->unpack($this->query('SELECT data,version,updated_at FROM jingo_posts WHERE id=?',[$p['id']])->fetch(PDO::FETCH_ASSOC));$this->db->commit();return $saved;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1] ?? null)===1062)throw new HttpError(409,'Mã hoặc đường dẫn bài viết đã tồn tại.');throw $e;}
    }
}
